import{_ as s,o as p,c as e,a2 as t}from"./chunks/framework.EUByU7Iq.js";const i=JSON.parse('{"title":"惜诵","description":"","frontmatter":{"title":"惜诵","date":"2026-11-24T00:00:00.000Z","seq":14,"categories":["美文","楚辞"],"collection":"《楚辞》","tags":["楚辞","先秦"],"poem":true,"poem_quote":false,"author":"屈原","source_book":"楚辞","prev":{"text":"天问","link":"/blogs/楚辞/天问.html"},"next":{"text":"涉江","link":"/blogs/楚辞/涉江.html"}},"headers":[],"relativePath":"blogs/楚辞/惜诵.md","filePath":"blogs/楚辞/惜诵.md"}'),o={name:"blogs/楚辞/惜诵.md"};function l(n,a,c,m,z,r){return p(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="惜诵" tabindex="-1">惜诵 <a class="header-anchor" href="#惜诵" aria-label="Permalink to &quot;惜诵&quot;">​</a></h1><p class="poem-meta">先秦 · 屈原　·　九章</p><div class="poem"><p class="poem-stanza">惜诵以致愍兮，发愤以抒情。</p><p class="poem-stanza">所作忠而言之兮，指苍天以为正。</p><p class="poem-stanza">令五帝使折中兮，戒六神与向服。</p><p class="poem-stanza">俾山川以备御兮，命咎繇使听直。</p><p class="poem-stanza">竭忠诚而事君兮，反离群而赘肬。</p><p class="poem-stanza">忘儇媚以背众兮，待明君其知之。</p><p class="poem-stanza">言与行其可迹兮，情与貌其不变。</p><p class="poem-stanza">故相臣莫若君兮，所以证之不远。</p><p class="poem-stanza">吾谊先君而后身兮，羌众人之所仇也。</p><p class="poem-stanza">专惟君而无他兮，又众兆之所雠也。</p><p class="poem-stanza">壹心而不豫兮，羌无可保也。</p><p class="poem-stanza">疾亲君而无他兮，有招祸之道也。</p><p class="poem-stanza">思君其莫我忠兮，忽忘身之贱贫。</p><p class="poem-stanza">事君而不贰兮，迷不知宠之门。</p><p class="poem-stanza">患何罪以遇罚兮，亦非余之所志也。</p><p class="poem-stanza">行不群以巅越兮，又众兆之所咍也。</p><p class="poem-stanza">纷逢尤以离谤兮，謇不可释也。</p><p class="poem-stanza">情沉抑而不达兮，又蔽而莫之白也。</p><p class="poem-stanza">心郁邑余侘傺兮，又莫察余之中情。</p><p class="poem-stanza">固烦言不可结而诒兮，愿陈志而无路。</p><p class="poem-stanza">退静默而莫余知兮，进号呼又莫吾闻。</p><p class="poem-stanza">申侘傺之烦惑兮，中闷瞀之忳忳。</p><p class="poem-stanza">昔余梦登天兮，魂中道而无杭。</p><p class="poem-stanza">吾使厉神占之兮，曰有志极而无旁。</p><p class="poem-stanza">终危独以离异兮，曰君可思而不可恃。</p><p class="poem-stanza">故众口其铄金兮，初若是而逢殆。</p><p class="poem-stanza">惩于羹者而吹齑兮，何不变此志也？</p><p class="poem-stanza">欲释阶而登天兮，犹有曩之态也。</p><p class="poem-stanza">众骇遽以离心兮，又何以为此伴也？</p><p class="poem-stanza">同极而异路兮，又何以为此援也？</p><p class="poem-stanza">晋申生之孝子兮，父信谗而不好。</p><p class="poem-stanza">行婞直而不豫兮，鲧功用而不就。</p><p class="poem-stanza">吾闻作忠以造怨兮，忽谓之过言。</p><p class="poem-stanza">九折臂而成医兮，吾至今而知其信然。</p><p class="poem-stanza">矰弋机而在上兮，罻罗张而在下。</p><p class="poem-stanza">设张辟以娱君兮，愿侧身而无所。</p><p class="poem-stanza">欲儃徊以干傺兮，恐重患而离尤。</p><p class="poem-stanza">欲高飞而远集兮，君罔谓汝何之？</p><p class="poem-stanza">欲横奔而失路兮，盖志坚而不忍。</p><p class="poem-stanza">背膺牉以交痛兮，心郁结而纡轸。</p><p class="poem-stanza">擣木兰以矫蕙兮，糳申椒以为粮。</p><p class="poem-stanza">播江离与滋菊兮，愿春日以为糗芳。</p><p class="poem-stanza">恐情质之不信兮，故重著以自明。</p><p class="poem-stanza">矫兹媚以私处兮，愿曾思而远身。</p></div>',3)])])}const d=s(o,[["render",l]]);export{i as __pageData,d as default};
